import { MakeLogicType, actions, connect, kea, key, path, props, reducers, selectors } from 'kea'

import { FEATURE_FLAGS } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'
import { userHasAccess } from 'lib/utils/accessControlUtils'

import { ErrorTrackingLinkedDataKind } from '~/queries/schema/schema-general'
import { AccessControlLevel, AccessControlResourceType } from '~/types'

export interface IssueLinkedDataLogicProps {
    issueId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueLinkedDataLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    linkedDataKinds: ErrorTrackingLinkedDataKind[]
    requiredLinks: ErrorTrackingLinkedDataKind[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueLinkedDataLogicActions {
    clearRequiredLinks: () => {
        value: true
    }
    setLinkRequired: (
        kind: ErrorTrackingLinkedDataKind,
        required: boolean
    ) => {
        kind: ErrorTrackingLinkedDataKind
        required: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueLinkedDataLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        linkedDataKinds: (featureFlags: FeatureFlagsSet) => ErrorTrackingLinkedDataKind[]
    }
}

export type issueLinkedDataLogicType = MakeLogicType<
    issueLinkedDataLogicValues,
    issueLinkedDataLogicActions,
    IssueLinkedDataLogicProps,
    issueLinkedDataLogicMeta
>

export const issueLinkedDataLogic = kea<issueLinkedDataLogicType>([
    path((key) => ['products', 'error_tracking', 'scenes', 'ErrorTrackingIssueScene', 'issueLinkedDataLogic', key]),
    props({} as IssueLinkedDataLogicProps),
    key((props) => props.issueId),

    connect(() => ({
        values: [featureFlagLogic, ['featureFlags']],
    })),

    actions({
        clearRequiredLinks: true,
        setLinkRequired: (kind: ErrorTrackingLinkedDataKind, required: boolean) => ({ kind, required }),
    }),

    reducers({
        requiredLinks: [
            [] as ErrorTrackingLinkedDataKind[],
            {
                setLinkRequired: (state, { kind, required }) => {
                    const withoutKind = state.filter((existing) => existing !== kind)
                    return required ? [...withoutKind, kind] : withoutKind
                },
                clearRequiredLinks: () => [],
            },
        ],
    }),

    selectors({
        linkedDataKinds: [
            (s) => [s.featureFlags],
            (featureFlags: FeatureFlagsSet): ErrorTrackingLinkedDataKind[] =>
                featureFlags[FEATURE_FLAGS.LOGS_IN_ERROR_TRACKING] &&
                userHasAccess(AccessControlResourceType.Logs, AccessControlLevel.Viewer)
                    ? ['recording', 'logs']
                    : ['recording'],
        ],
    }),
])
